# 同步调用：下单前检查库存
class InventoryServiceClient:
    def __init__(self, base_url: str):
        self._base_url = base_url
    def check_availability(self, product_id: str, quantity: int) -> bool:
        try:
            response = httpx.get(
                f"{self._base_url}/inventory/{product_id}/availability",
                params={"quantity": quantity},
                timeout=3.0
            )
            response.raise_for_status()
            return response.json()["available"]
        except httpx.TimeoutException:
            raise ServiceUnavailableError("库存服务暂时不可用")
# 异步发布：下单后发布事件，不等库存服务处理
class OrderApplicationService:
    def place_order(self, command) -> str:
        order = Order(OrderId(), command.customer_id)
        order.place()
        self._order_repo.save(order)
        self._event_publisher.publish(
            topic="order.placed",
            message={"order_id": str(order.id), "items": command.items}
        )
        return str(order.id)
